"""Command line interface: ``pennywise`` / ``python -m pennywise``."""

import argparse
import csv
import io
import json
import os
import sys

from .ledger import (
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    format_amount,
    format_entry,
    parse,
    parse_date,
    parse_line,
    sort_entries,
)


class _Fail(Exception):
    """Abort with a message on stderr and an exit code."""

    def __init__(self, message, code):
        super().__init__(message)
        self.code = code


def _date_arg(text):
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser():
    p = argparse.ArgumentParser(prog="pennywise", description="Report on a plain-text ledger.")
    sub = p.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    s = sub.add_parser("balance", help="print the total")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("summary", help="print totals per category or month")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--by", choices=["category", "month"], default="category")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("list", help="print entries, oldest first")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--category")
    s.add_argument("--since", type=_date_arg, metavar="DATE")
    s.add_argument("--until", type=_date_arg, metavar="DATE")
    s.add_argument("--json", action="store_true", help="print JSON")

    s = sub.add_parser("add", help="append an entry")
    s.add_argument("file", metavar="FILE")
    s.add_argument("date", metavar="DATE")
    s.add_argument("category", metavar="CATEGORY")
    s.add_argument("amount", metavar="AMOUNT")
    s.add_argument("note", metavar="NOTE", nargs="?", default="")

    s = sub.add_parser("export", help="print entries as CSV")
    s.add_argument("file", metavar="FILE")
    s.add_argument("--format", choices=["csv"], default="csv")
    return p


def _read_entries(path):
    try:
        if path == "-":
            text = sys.stdin.read()
        else:
            with open(path, encoding="utf-8") as fh:
                text = fh.read()
    except (OSError, UnicodeDecodeError) as exc:
        raise _Fail("pennywise: %s: cannot read: %s" % (path, exc), 2)
    try:
        return parse(text)
    except ParseError as exc:
        raise _Fail("pennywise: %s: %s" % (path, exc), 1)


def _json(obj):
    return json.dumps(obj) + "\n"


def _entry_dict(e):
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


def _cmd_balance(args):
    total = format_amount(balance(_read_entries(args.file)))
    return _json({"balance": total}) if args.json else total + "\n"


def _cmd_summary(args):
    entries = _read_entries(args.file)
    totals = by_category(entries) if args.by == "category" else by_month(entries)
    names = sorted(totals)
    if args.json:
        return _json({n: format_amount(totals[n]) for n in names})
    return "".join("%s  %s\n" % (n, format_amount(totals[n])) for n in names)


def _selected(args):
    entries = _read_entries(args.file)
    return sort_entries(filter_entries(entries, args.category, args.since, args.until))


def _cmd_list(args):
    entries = _selected(args)
    if args.json:
        return _json([_entry_dict(e) for e in entries])
    return "".join(format_entry(e) + "\n" for e in entries)


def _cmd_export(args):
    entries = sort_entries(_read_entries(args.file))
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator="\n")
    w.writerow(["date", "category", "amount", "note"])
    for e in entries:
        w.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    return buf.getvalue()


def _cmd_add(args):
    path = args.file
    if path == "-":
        raise _Fail("pennywise: add: FILE cannot be '-' (stdin)", 2)
    try:
        with open(path, "rb") as fh:
            existing = fh.read()
    except FileNotFoundError:
        existing = b""
    except OSError as exc:
        raise _Fail("pennywise: %s: cannot read: %s" % (path, exc), 2)

    number = len(existing.decode("utf-8", errors="replace").splitlines()) + 1
    try:
        if not args.category or len(args.category.split()) != 1:
            raise ParseError("category must be one non-empty word", number)
        for value in (args.date, args.amount):
            if len(value.split()) != 1:
                raise ParseError("invalid field %r" % value, number)
        line = " ".join([args.date, args.category, args.amount] + ([args.note] if args.note else []))
        if len(line.splitlines()) != 1:
            raise ParseError("note must be a single line", number)
        entry = parse_line(line, number)
    except ParseError as exc:
        raise _Fail("pennywise: %s: %s" % (path, exc), 1)

    out = format_entry(entry)
    prefix = b"\n" if existing and not existing.endswith(b"\n") else b""
    try:
        with open(path, "ab") as fh:
            fh.write(prefix + (out + "\n").encode("utf-8"))
    except OSError as exc:
        raise _Fail("pennywise: %s: cannot write: %s" % (path, exc), 2)
    return out + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def main(argv=None):
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    try:
        output = _COMMANDS[args.command](args)
    except _Fail as exc:
        print(str(exc), file=sys.stderr)
        return exc.code
    try:
        sys.stdout.write(output)
        sys.stdout.flush()
    except BrokenPipeError:
        # Reader went away early (e.g. ``| head -1``). Exit quietly like other
        # Unix tools; point stdout at devnull so the flush at interpreter exit
        # cannot raise again.
        try:
            fileno = sys.stdout.fileno()
            devnull = os.open(os.devnull, os.O_WRONLY)
            try:
                os.dup2(devnull, fileno)
            finally:
                os.close(devnull)
        except (OSError, ValueError, AttributeError):
            pass
    return 0
"""Ledger parsing, aggregation, filtering and formatting."""

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal, localcontext

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(\.[0-9]{1,2})?")


class ParseError(ValueError):
    """A ledger line is malformed. ``line`` is its 1-based number."""

    def __init__(self, message, line):
        super().__init__("line %d: %s" % (line, message))
        self.line = line
        self.reason = message


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def parse_date(text):
    """Parse ``YYYY-MM-DD`` (ASCII digits, a real date) or raise ValueError."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def parse_amount(text):
    """Parse an amount with optional sign and at most 2 decimals, or raise ValueError."""
    if not _AMOUNT_RE.fullmatch(text):
        raise ValueError("invalid amount %r (optional sign, at most 2 decimals)" % text)
    return Decimal(text)


def parse_line(line, number):
    """Parse one non-blank, non-comment ledger line into an Entry."""
    fields = line.strip().split(None, 3)
    if len(fields) < 3:
        raise ParseError("expected DATE CATEGORY AMOUNT [NOTE]", number)
    try:
        date = parse_date(fields[0])
        amount = parse_amount(fields[2])
    except ValueError as exc:
        raise ParseError(str(exc), number) from None
    note = fields[3].strip() if len(fields) == 4 else ""
    return Entry(date, fields[1].lower(), amount, note)


def parse(text):
    """Parse ledger text into a list of Entry, in file order."""
    entries = []
    for number, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        entries.append(parse_line(line, number))
    return entries


def balance(entries):
    total = Decimal(0)
    for e in entries:
        total += e.amount
    return total


def _group(entries, key):
    totals = {}
    for e in entries:
        k = key(e)
        totals[k] = totals.get(k, Decimal(0)) + e.amount
    return totals


def by_category(entries):
    return _group(entries, lambda e: e.category)


def by_month(entries):
    return _group(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(entries, category=None, since=None, until=None):
    wanted = category.lower() if category is not None else None
    result = []
    for e in entries:
        if wanted is not None and e.category != wanted:
            continue
        if since is not None and e.date < since:
            continue
        if until is not None and e.date > until:
            continue
        result.append(e)
    return result


def format_amount(amount):
    """Two decimals, never ``-0.00``."""
    with localcontext() as ctx:
        ctx.prec = max(ctx.prec, 60)
        q = amount.quantize(Decimal("0.01"))
    if q == 0:
        q = Decimal("0.00")
    return "{:.2f}".format(q)


def format_entry(entry):
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line


def sort_entries(entries):
    """Oldest first; entries on the same day keep file order."""
    return sorted(entries, key=lambda e: e.date)
