"""Ledger parsing, aggregation, filtering and formatting."""

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal, localcontext

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(\.[0-9]{1,2})?")


class ParseError(ValueError):
    """A ledger line is malformed. ``line`` is its 1-based number."""

    def __init__(self, message, line):
        super().__init__("line %d: %s" % (line, message))
        self.line = line
        self.reason = message


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def parse_date(text):
    """Parse ``YYYY-MM-DD`` (ASCII digits, a real date) or raise ValueError."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def parse_amount(text):
    """Parse an amount with optional sign and at most 2 decimals, or raise ValueError."""
    if not _AMOUNT_RE.fullmatch(text):
        raise ValueError("invalid amount %r (optional sign, at most 2 decimals)" % text)
    return Decimal(text)


def parse_line(line, number):
    """Parse one non-blank, non-comment ledger line into an Entry."""
    fields = line.strip().split(None, 3)
    if len(fields) < 3:
        raise ParseError("expected DATE CATEGORY AMOUNT [NOTE]", number)
    try:
        date = parse_date(fields[0])
        amount = parse_amount(fields[2])
    except ValueError as exc:
        raise ParseError(str(exc), number) from None
    note = fields[3].strip() if len(fields) == 4 else ""
    return Entry(date, fields[1].lower(), amount, note)


def parse(text):
    """Parse ledger text into a list of Entry, in file order."""
    entries = []
    for number, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        entries.append(parse_line(line, number))
    return entries


def balance(entries):
    total = Decimal(0)
    for e in entries:
        total += e.amount
    return total


def _group(entries, key):
    totals = {}
    for e in entries:
        k = key(e)
        totals[k] = totals.get(k, Decimal(0)) + e.amount
    return totals


def by_category(entries):
    return _group(entries, lambda e: e.category)


def by_month(entries):
    return _group(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(entries, category=None, since=None, until=None):
    wanted = category.lower() if category is not None else None
    result = []
    for e in entries:
        if wanted is not None and e.category != wanted:
            continue
        if since is not None and e.date < since:
            continue
        if until is not None and e.date > until:
            continue
        result.append(e)
    return result


def format_amount(amount):
    """Two decimals, never ``-0.00``."""
    with localcontext() as ctx:
        ctx.prec = max(ctx.prec, 60)
        q = amount.quantize(Decimal("0.01"))
    if q == 0:
        q = Decimal("0.00")
    return "{:.2f}".format(q)


def format_entry(entry):
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line


def sort_entries(entries):
    """Oldest first; entries on the same day keep file order."""
    return sorted(entries, key=lambda e: e.date)
